import{_ as t,o,c as a,ag as i}from"./chunks/framework.wGDfT7ie.js";const u=JSON.parse('{"title":"How it works (user flow)","description":"","frontmatter":{},"headers":[],"relativePath":"flow.md","filePath":"flow.md"}'),r={name:"flow.md"};function n(s,e,l,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="how-it-works-user-flow" tabindex="-1">How it works (user flow) <a class="header-anchor" href="#how-it-works-user-flow" aria-label="Permalink to &quot;How it works (user flow)&quot;">​</a></h1><p>High-level flow — no API or implementation details.</p><h2 id="_1-connect-and-set-constraints" tabindex="-1">1. Connect and set constraints <a class="header-anchor" href="#_1-connect-and-set-constraints" aria-label="Permalink to &quot;1. Connect and set constraints&quot;">​</a></h2><ul><li>Connect your Starknet wallet (e.g. ArgentX, Braavos) on <a href="https://zkde.fi" target="_blank" rel="noreferrer">zkde.fi</a>.</li><li>Set your constraints: e.g. max position size, allowed protocols (Pools, Ekubo, JediSwap). Optionally use session keys so the agent can act within these limits without signing every time.</li></ul><h2 id="_2-proof-gated-deposit" tabindex="-1">2. Proof-gated deposit <a class="header-anchor" href="#_2-proof-gated-deposit" aria-label="Permalink to &quot;2. Proof-gated deposit&quot;">​</a></h2><ul><li>Open <strong>Pools</strong> (or another protocol tab).</li><li>Enter amount and optional max position.</li><li>Click <strong>Deposit with proof</strong>. The app requests a constraint proof from the backend (which calls the Obsqra prover). When the proof is ready, you see <strong>Proof ready</strong>.</li><li>Click <strong>Sign &amp; deposit</strong>. Your wallet signs the transaction that calls the ProofGatedYieldAgent contract with the proof. The contract checks the proof against Integrity; if valid, the deposit executes. You get a tx hash and a link to the explorer.</li></ul><h2 id="_3-selective-disclosure-compliance" tabindex="-1">3. Selective disclosure (compliance) <a class="header-anchor" href="#_3-selective-disclosure-compliance" aria-label="Permalink to &quot;3. Selective disclosure (compliance)&quot;">​</a></h2><ul><li>In the <strong>Compliance / Disclosure</strong> panel, set the statement type, threshold, and result you want to prove.</li><li>Click <strong>Generate disclosure proof</strong>. When ready, click <strong>Register on-chain</strong>. Your wallet signs; the SelectiveDisclosure contract stores the proof. You’ve proved a statement without revealing your full history.</li></ul><h2 id="_4-private-deposit-optional" tabindex="-1">4. Private deposit (optional) <a class="header-anchor" href="#_4-private-deposit-optional" aria-label="Permalink to &quot;4. Private deposit (optional)&quot;">​</a></h2><ul><li>Open the <strong>Private</strong> tab.</li><li>Enter the amount. Click <strong>Generate private deposit</strong>. The app creates a commitment and proof calldata (Garaga).</li><li>Click <strong>Sign &amp; submit</strong>. Your wallet signs the ConfidentialTransfer.private_deposit transaction. Amounts and balances stay confidential; only commitments are visible on-chain.</li></ul><p>Next: <a href="/docs/innovation.html">Innovation</a></p>',11)])])}const f=t(r,[["render",n]]);export{u as __pageData,f as default};
